const run = async (sql:string,...values:any[]) => db().prepare(sql).bind(...values).run();
const fail=(status:number,error:string):never=>{throw Object.assign(new Error(error),{status});};
const token=(n=32)=>btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(n)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
