const cookie=(r:Request,key:string)=>r.headers.get('cookie')?.split(';').map(x=>x.trim()).find(x=>x.startsWith(key+'='))?.slice(key.length+1)||'';
const json=(data:any,status=200,cookies:string[]=[]):Response=>{const h=new Headers({'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'no-referrer','x-frame-options':'DENY','cross-origin-resource-policy':'same-origin','permissions-policy':'camera=(), microphone=(), geolocation=()','strict-transport-security':'max-age=31536000; includeSubDomains'});for(const c of cookies)h.append('set-cookie',c);return new Response(JSON.stringify(data),{status,headers:h});};
const setCookie=(key:string,value:string,age:number)=>`${key}=${value}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${age}`;
async function ensureMiniSchema(){
  // Keep long-lived D1 databases compatible even when a preview or deployment starts
  // before the migration runner has observed the newest migration journal entry.
  await run("CREATE TABLE IF NOT EXISTS football_entities(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,name_ar TEXT NOT NULL,name_en TEXT NOT NULL DEFAULT '',image_key TEXT NOT NULL DEFAULT '',image_source TEXT NOT NULL DEFAULT '',image_license TEXT NOT NULL DEFAULT '',fallback TEXT NOT NULL DEFAULT '',metadata TEXT NOT NULL DEFAULT '{}',updated_at INTEGER NOT NULL)");
  await run('CREATE INDEX IF NOT EXISTS idx_football_entities_type ON football_entities(entity_type)');
  await run("CREATE TABLE IF NOT EXISTS mini_game_rounds(id TEXT PRIMARY KEY,game_slug TEXT NOT NULL,difficulty TEXT NOT NULL,prompt TEXT NOT NULL,solution TEXT NOT NULL,accepted TEXT NOT NULL DEFAULT '[]',explanation TEXT NOT NULL DEFAULT '',visual_data TEXT NOT NULL DEFAULT '{}',source TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)");
  await run('CREATE INDEX IF NOT EXISTS idx_mini_game_rounds_pool ON mini_game_rounds(game_slug,status,difficulty)');
  await run("CREATE TABLE IF NOT EXISTS mini_game_rooms(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),config TEXT NOT NULL,state TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,expires_at INTEGER NOT NULL)");
  await run('CREATE INDEX IF NOT EXISTS idx_mini_game_rooms_owner ON mini_game_rooms(owner_id,status)');
  await run('CREATE TABLE IF NOT EXISTS mini_game_members(room_id TEXT NOT NULL REFERENCES mini_game_rooms(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,team INTEGER NOT NULL,name TEXT NOT NULL,kicked INTEGER NOT NULL DEFAULT 0,joined_at INTEGER NOT NULL,last_seen INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(room_id,user_id))');
  await run('CREATE INDEX IF NOT EXISTS idx_mini_game_members_seen ON mini_game_members(room_id,last_seen)');
  await run('CREATE TABLE IF NOT EXISTS mini_game_events(id INTEGER PRIMARY KEY AUTOINCREMENT,room_id TEXT NOT NULL REFERENCES mini_game_rooms(id) ON DELETE CASCADE,message TEXT NOT NULL,created_at INTEGER NOT NULL)');
  await run('CREATE INDEX IF NOT EXISTS idx_mini_game_events_room ON mini_game_events(room_id,id)');
  const columns=new Set((await all('PRAGMA table_info(mini_game_rounds)')).map(column=>column.name));
  if(!columns.has('accepted'))await run("ALTER TABLE mini_game_rounds ADD COLUMN accepted TEXT NOT NULL DEFAULT '[]'");
  if(!columns.has('explanation'))await run("ALTER TABLE mini_game_rounds ADD COLUMN explanation TEXT NOT NULL DEFAULT ''");
  if(!columns.has('visual_data'))await run("ALTER TABLE mini_game_rounds ADD COLUMN visual_data TEXT NOT NULL DEFAULT '{}'");
}
async function seed(previewRepair=false){
  const current=Number((await one("SELECT value FROM settings WHERE key='seed_version'"))?.value||0);
  if(current<BANK_VERSION){
    // The 6000+ question payload is only needed by an unseeded database.
    const list=(await import('@/seed/questions.json')).default as {version:number,tournaments:Row[],questions:Row[]};
    if(current<4)await run("DELETE FROM questions WHERE note='قاعدة كروية عامة تنطبق على مباريات هذه البطولة.'");
    if(!current)await db().batch(list.tournaments.map(t=>db().prepare('INSERT OR IGNORE INTO tournaments(id,name,active,position) VALUES(?,?,1,?)').bind(t.id,t.name,t.position)));
    const pending=list.questions.filter(q=>!current||Number(q.pack||1)>current),chunks:Row[][]=[];for(let i=0;i<pending.length;i+=80)chunks.push(pending.slice(i,i+80));
    for(let i=0;i<chunks.length;i+=4)await Promise.all(chunks.slice(i,i+4).map(chunk=>db().batch(chunk.map(q=>db().prepare("INSERT OR IGNORE INTO questions(id,tournament_id,letter,text,answer,difficulty,status,source,note,created_at,updated_at) VALUES(?,?,?,?,?,?,'published',?,?,?,?)").bind(q.id,q.tournament_id,q.letter,q.text,q.answer,q.difficulty,q.source,q.note||'',now(),now())))));
    await db().batch([['maintenance','false'],['default_theme','dark'],['max_players','64']].map(([k,v])=>db().prepare('INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)').bind(k,v)));
    await run("UPDATE settings SET value='dark' WHERE key='default_theme' AND value='auto'");await run("UPDATE users SET theme='dark' WHERE theme='auto'");await run("INSERT INTO settings(key,value) VALUES('seed_version',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",String(list.version));
  }
  if(previewRepair)await ensureMiniSchema();
  const miniCurrent=Number((await one("SELECT value FROM settings WHERE key='mini_seed_version'"))?.value||0);
  if(miniCurrent<MINI_CONTENT_VERSION){
    await run("UPDATE mini_game_rounds SET status='hidden',updated_at=? WHERE id='gt-argentina'",now());
    for(let i=0;i<MINI_ROUNDS.length;i+=40)await db().batch(MINI_ROUNDS.slice(i,i+40).map(round=>db().prepare("INSERT INTO mini_game_rounds(id,game_slug,difficulty,prompt,solution,accepted,explanation,visual_data,source,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET game_slug=excluded.game_slug,difficulty=excluded.difficulty,prompt=excluded.prompt,solution=excluded.solution,accepted=excluded.accepted,explanation=excluded.explanation,visual_data=excluded.visual_data,source=excluded.source,updated_at=excluded.updated_at").bind(round.id,round.game_slug,round.difficulty,round.prompt,round.solution,JSON.stringify(round.accepted),round.explanation,JSON.stringify(round.visual),round.source,round.status,now(),now())));
    const media=Object.entries(MINI_MEDIA);for(let i=0;i<media.length;i+=40)await db().batch(media.slice(i,i+40).map(([id,item])=>db().prepare("INSERT INTO football_entities(id,entity_type,name_ar,name_en,image_key,image_source,image_license,fallback,metadata,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET entity_type=excluded.entity_type,image_key=excluded.image_key,image_source=excluded.image_source,image_license=excluded.image_license,fallback=excluded.fallback,updated_at=excluded.updated_at").bind(id,item.type,item.fallback,item.fallback,item.url,item.source,item.license,item.fallback,'{}',now())));
    await run("INSERT INTO settings(key,value) VALUES('mini_seed_version',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",String(MINI_CONTENT_VERSION));
  }
}
// Each Worker isolate needs to check the seed once, not on every API request.
let seedPromise:Promise<void>|null=null;
function ensureSeed(previewRepair=false){if(!seedPromise)seedPromise=seed(previewRepair).catch(e=>{seedPromise=null;throw e;});return seedPromise;}
let lastCleanup=0;
async function cleanup(){const t=now();if(t-lastCleanup<30000)return;lastCleanup=t;const oldRooms=await all('SELECT id FROM rooms WHERE expires_at<?',t),oldMini=await all('SELECT id FROM mini_game_rooms WHERE expires_at<?',t),statements:D1PreparedStatement[]=[db().prepare('DELETE FROM sessions WHERE expires_at<?').bind(t),db().prepare('DELETE FROM challenges WHERE expires_at<?').bind(t),db().prepare('DELETE FROM rates WHERE reset_at<?').bind(t),db().prepare('DELETE FROM events WHERE created_at<?').bind(t-2592000000),db().prepare('DELETE FROM mini_game_events WHERE created_at<?').bind(t-2592000000),db().prepare('DELETE FROM audit WHERE created_at<?').bind(t-7776000000)];for(const {id} of oldRooms)statements.push(db().prepare('DELETE FROM match_players WHERE match_id IN (SELECT id FROM matches WHERE room_id=?)').bind(id),db().prepare('DELETE FROM matches WHERE room_id=?').bind(id),db().prepare('DELETE FROM events WHERE room_id=?').bind(id),db().prepare('DELETE FROM members WHERE room_id=?').bind(id),db().prepare('DELETE FROM rooms WHERE id=?').bind(id));for(const {id} of oldMini)statements.push(db().prepare('DELETE FROM mini_game_events WHERE room_id=?').bind(id),db().prepare('DELETE FROM mini_game_members WHERE room_id=?').bind(id),db().prepare('DELETE FROM mini_game_rooms WHERE id=?').bind(id));for(let i=0;i<statements.length;i+=80)await db().batch(statements.slice(i,i+80));}
async function limit(key:string,max:number,ms:number,amount=1){const hashed=await digest(key),t=now();const result=await one('INSERT INTO rates(key,count,reset_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN reset_at<? THEN excluded.count ELSE count+excluded.count END,reset_at=CASE WHEN reset_at<? THEN excluded.reset_at ELSE reset_at END RETURNING count',hashed,amount,t+ms,t,t);if(result.count>max)fail(429,'طلبات كثيرة. انتظر قليلًا ثم حاول مرة أخرى.');}
// Reserve a short-lived poll allowance in D1 instead of writing to D1 on every screen refresh.
const pollAllowances=new Map<string,{left:number,expires:number}>();
async function limitPoll(key:string,max:number){const t=now(),allowance=pollAllowances.get(key);if(allowance&&allowance.expires>t&&allowance.left>0){allowance.left--;return;}await limit('room-poll:'+key,max,60000,50);if(pollAllowances.size>8192)pollAllowances.clear();pollAllowances.set(key,{left:49,expires:t+5000});}
async function sessionContext(r:Request):Promise<{session:Row|null,user:Row|null}>{const raw=cookie(r,'hk_sid');if(!/^[A-Za-z0-9_-]{43}$/.test(raw))return {session:null,user:null};const row=await one("SELECT s.*,u.id joined_user_id,u.name joined_user_name,u.theme joined_user_theme,u.blocked joined_user_blocked FROM sessions s LEFT JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.kind='guest' AND s.expires_at>?",await digest(raw),now());if(!row)return {session:null,user:null};const user=row.joined_user_id&&!row.joined_user_blocked?{id:row.joined_user_id,name:row.joined_user_name,theme:row.joined_user_theme}:null;return {session:row,user};}
// Settings can change in the admin panel; keep the cache short and invalidate on writes.
let settingsCache:Record<string,string>|null=null,settingsExpires=0;
async function settings():Promise<Record<string,string>>{if(settingsCache&&now()<settingsExpires)return settingsCache;const values=await all('SELECT key,value FROM settings');const latest:Record<string,string>=Object.fromEntries(values.map(x=>[x.key,x.value]));settingsCache=latest;settingsExpires=now()+5000;return latest;}
async function setting(k:string,f=''){return (await settings())[k]||f;}
let tournamentsCache:Row[]|null=null,tournamentsExpires=0;
async function publicTournaments(){if(tournamentsCache&&now()<tournamentsExpires)return tournamentsCache;tournamentsCache=await all("SELECT t.id,t.name,t.position,count(q.id) questions FROM tournaments t LEFT JOIN questions q ON q.tournament_id=t.id AND q.status='published' WHERE t.active=1 GROUP BY t.id ORDER BY t.position");tournamentsExpires=now()+60000;return tournamentsCache;}
async function payload(s:Row,admin:Row|null,u:Row|null){const options=await settings();return {user:u?{id:u.id,name:u.name,theme:u.theme}:null,admin,csrf:s.csrf,bot:{provider:'captcha'},defaultTheme:options.default_theme||'dark',maintenance:options.maintenance==='true',supportUrl:normalizeSupportUrl(options.support_url)||null};}
async function body(r:Request,max=8192):Promise<Row>{if(!r.headers.get('content-type')?.startsWith('application/json'))fail(415,'نوع الطلب غير صحيح.');if(Number(r.headers.get('content-length')||0)>max)fail(413,'الطلب كبير جدًا.');const reader=r.body?.getReader();if(!reader)return fail(400,'بيانات الطلب غير صحيحة.');const chunks:Uint8Array[]= [];let size=0;for(;;){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>max){await reader.cancel();fail(413,'الطلب كبير جدًا.');}chunks.push(value);}const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}let data;try{data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}catch{fail(400,'بيانات الطلب غير صحيحة.');}if(!data||typeof data!=='object'||Array.isArray(data))fail(400,'بيانات الطلب غير صحيحة.');return data;}
function validName(v:any){const n=String(v||'').normalize('NFKC').trim();if(n.length<2||n.length>24||/[\p{Cc}\p{Cf}<>]/u.test(n))fail(422,'اكتب اسمًا من حرفين إلى ٢٤ حرفًا.');return n;}
function questionFilter(config:Row,letter?:string){const ids=config.tournaments,values:any[]=[...ids];let sql=`q.status='published' AND t.active=1 AND q.tournament_id IN (${ids.map(()=>'?').join(',')})`;if(config.difficulty!=='all'){sql+=' AND q.difficulty=?';values.push(config.difficulty);}if(letter){sql+=' AND q.letter=?';values.push(letter);}return {sql,values};}
async function questionCoverage(config:Row){const collect=async(candidate:Row)=>{const filter=questionFilter(candidate),rows=await all(`SELECT q.letter,count(*) count FROM questions q JOIN tournaments t ON t.id=q.tournament_id WHERE ${filter.sql} GROUP BY q.letter`,...filter.values),coverage:Record<string,number>={};for(const row of rows)coverage[row.letter]=Number(row.count);return coverage;},preferred=await collect(config);return Object.values(preferred).reduce((sum,count)=>sum+count,0)>=config.size*config.size||config.difficulty==='all'?preferred:collect({...config,difficulty:'all'});}
