async function getRoom(id:string){const row=await one('SELECT * FROM rooms WHERE id=?',id);if(!row)fail(404,'الغرفة غير موجودة.');if(row.status!=='open'||row.expires_at<now())fail(410,'انتهت هذه الغرفة.');if(row.expires_at<now()+8*60*1000){row.expires_at=now()+10*60*1000;await run('UPDATE rooms SET expires_at=? WHERE id=?',row.expires_at,id);}return {...row,config:JSON.parse(row.config),state:JSON.parse(row.state)};}
async function members(id:string){return all('SELECT user_id id,name,team,last_seen FROM members WHERE room_id=? AND kicked=0 ORDER BY joined_at',id);}
