async function save(room:Row,message:string){const stamp=now(),statements=[db().prepare('UPDATE rooms SET state=?,version=version+1,updated_at=?,expires_at=? WHERE id=? AND version=?').bind(JSON.stringify(room.state),stamp,stamp+10*60*1000,room.id,room.version)];if(message)statements.push(db().prepare('INSERT INTO events(room_id,message,created_at) VALUES(?,?,?)').bind(room.id,message,stamp));const [result]=await db().batch(statements);if(result.meta.changes!==1)fail(409,'تغيرت المباراة، حاول مرة أخرى.');room.version++;}
function remember(s:Row){const copy=structuredClone(s);delete copy.history;s.history.push(copy);s.history=s.history.slice(-40);}
