async function updateMatch(room:Row){const s=room.state,key=s.matchKey||s.round;const statements=[db().prepare('DELETE FROM match_players WHERE match_id IN (SELECT id FROM matches WHERE room_id=? AND round=?)').bind(room.id,key),db().prepare('DELETE FROM matches WHERE room_id=? AND round=?').bind(room.id,key)];if(s.winner){const id=token(18);statements.push(db().prepare('INSERT INTO matches(id,room_id,round,winner,board,finished_at) VALUES(?,?,?,?,?,?)').bind(id,room.id,key,s.winner,JSON.stringify(s.board),now()));for(const p of await members(room.id))statements.push(db().prepare('INSERT INTO match_players(match_id,user_id,won) VALUES(?,?,?)').bind(id,p.id,Number(p.team===s.winner)));}await db().batch(statements);}
